Since Next.js components are isolated, you cannot rely on local state (like `useState` inside the component) to track which tooltip is open. Instead, you must lift the state up to a Context that wraps your entire application (or the specific section where these tooltips live).

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to manage the global state of the tooltips.

`src/context/TooltipContext.tsx`

```tsx
'use client'; // Required for Next.js App Router

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of our state
interface TooltipState {
  isOpen: boolean;
  content: string;
  position: { top: number; left: number };
  close: () => void;
  open: (content: string, position: { top: number; left: number }) => void;
}

const TooltipContext = createContext<TooltipState | undefined>(undefined);

interface TooltipProviderProps {
  children: ReactNode;
}

export const TooltipProvider: React.FC<TooltipProviderProps> = ({ children }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [content, setContent] = useState('');
  const [position, setPosition] = useState({ top: 0, left: 0 });

  const close = useCallback(() => {
    setIsOpen(false);
    setContent('');
    setPosition({ top: 0, left: 0 });
  }, []);

  const open = useCallback((newContent: string, newPos: { top: number; left: number }) => {
    setContent(newContent);
    setPosition(newPos);
    setIsOpen(true);
  }, []);

  return (
    <TooltipContext.Provider value={{ isOpen, content, position, close, open }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

